import { gfx, RenderTexture } from "cc";
import { VideoChunk, PlayMode, IWaninPlayer } from "./wanin-player.interface";
import { VideoFile } from "./video-file";
import Decoder from "./decoder";
import EventManager from "./event-manager";

export default class WaninPlayer implements IWaninPlayer {
    /**
     * prepare中的videoChunk
     */
    private videoChunks: VideoChunk[] = [];

    /**
     * 播放清單
     */
    #playList: number[] = [];

    /**
     * 播放模式
     */
    #playMode: PlayMode = PlayMode.Once;

    /**
     * 解碼器主程序
     */
    #decoder: Decoder | null = null;

    /**
     * 解碼要更新的renderTexture
     */
    #renderTexture = new RenderTexture();
    #gfxTexture: gfx.Texture | null = null;
    #TextureCopy: gfx.BufferTextureCopy | null = null;

    /** 自更新影片畫面的TimeOut */
    #updateTimeOut: number | null = null;

    #updateTimestamp = 0;

    /** 剩餘播放列表 
     * -1為播放清單開頭 
     * -2是循環串接點  
     * 
     * @example
     * this.waninPlayer.play(PlayMode.RepeatAll, [1, 2]);
     * 
     * [-1,1,2, -2 ,1,2, -2, 1,2]
     * 
    */
    #remainingPlaylist: number[] = []; 

    public event: EventManager = new EventManager();

    constructor() {
    }

    public async loadVideo(urls: RequestInfo[] | URL[]): Promise<void> {

        return new Promise(async (res, rej) => {
            if (urls.length == 0) {
                rej();

                return;
            }

            this.videoChunks = await VideoFile.getVideoData(urls);

            if (this.videoChunks.length === 0) {
                rej();

                return;
            }

            console.log(`this.#videoChunks `, this.videoChunks)
            res();
        });
    }

    public createDecoder() {
        if (this.videoChunks.length === 0) {
            console.error("videoChunks 找不到");
            return;
        }

        this.#decoder = new Decoder({
            codec: this.videoChunks[0].codec,
            codedHeight: this.videoChunks[0].height,
            codedWidth: this.videoChunks[0].width,
            description: this.videoChunks[0].description,
            optimizeForLatency: true,
            hardwareAcceleration: 'prefer-hardware',
        });

        const colorAttachment = new gfx.ColorAttachment(gfx.Format.RGBA8, 1, gfx.LoadOp.DISCARD, gfx.StoreOp.DISCARD);
        const pass = new gfx.RenderPassInfo([colorAttachment], undefined, undefined);
        this.#renderTexture.initialize(
            {
                width: this.videoChunks[0].width,
                height: this.videoChunks[0].height,
                externalFlag: gfx.TextureFlagBit.EXTERNAL_OES | gfx.TextureFlagBit.MUTABLE_STORAGE,
                passInfo: pass,
            }
        )

        const textureSubresLayers = new gfx.TextureSubresLayers();
        textureSubresLayers.mipLevel = 0;
        const Offset = new gfx.Extent(this.videoChunks[0].width, this.videoChunks[0].height);
        this.#TextureCopy = new gfx.BufferTextureCopy();
        this.#TextureCopy.texSubres = textureSubresLayers;
        this.#TextureCopy.texExtent = Offset;
        this.#gfxTexture = this.#renderTexture.getGFXTexture();
        this.#decoder.setVideoChunks(this.videoChunks);
        this.#updateTimestamp = this.videoChunks[0].updateTimestamp;
    }

    public play(mode: PlayMode = PlayMode.Once, list: number[] = []) {
        if (this.#decoder === null) {
            console.error("解碼器尚未建立。")

            return;
        }

        this.#playMode = mode;

        if (list.length === 0) {
            this.#playList = this.videoChunks.map(v => v.id);
        }
        else {
            this.#playList = [...list];
        }

        this.#decoder.playListDequeue = (list) => {
            if (this.#decoder === null) {
                console.error("解碼器尚未建立。")
                return;
            }

            if (list.length === 0) {
                switch (this.#playMode) {
                    case PlayMode.RepeatAll:
                    case PlayMode.AppendRepeatAll:
                        this.#remainingPlaylist = this.#remainingPlaylist.concat(-2 ,this.#playList)
                        this.#decoder.playListQueue = [...this.#playList];
                        break;
                    case PlayMode.RepeatLast:
                    case PlayMode.AppendRepeatLast:
                        this.#remainingPlaylist = this.#remainingPlaylist.concat(-2 ,this.#playList[this.#playList.length - 1])
                        this.#decoder.playListQueue = [this.#playList[this.#playList.length - 1]]
                        break;
                }
            }
        };

        if(this.#decoder.getIsPlayer() && (this.#playMode === PlayMode.AppendRepeatAll || this.#playMode === PlayMode.AppendRepeatLast || this.#playMode === PlayMode.AppendOnce)) {
            this.#decoder.playListQueue = this.#decoder.playListQueue.concat(this.#playList);
            this.#remainingPlaylist = this.#remainingPlaylist.concat(-2 ,this.#playList);

        } else {
            if (this.#updateTimeOut !== null) {
                clearTimeout(this.#updateTimeOut);
            }
    
            this.#updateTimeOut = setTimeout(this.update.bind(this), this.#updateTimestamp);
            this.#remainingPlaylist = [-1].concat(this.#playList);
            this.#decoder.startPlayVideo(this.#playList).then();
        }
    }

    private update() {
        if (!this.#decoder) {
            return;
        }

        // console.log("this.#decoderPlayListState",  this.#decoderPlayListState);

        const frameData = this.#decoder.getFrameOutput();

        if (frameData !== null && this.#gfxTexture !== null && this.#TextureCopy !== null) {
            console.log("正在播放的frame", frameData);

            gfx.deviceManager.gfxDevice.copyTexImagesToTexture([frameData.videoFrame], this.#gfxTexture, [this.#TextureCopy]);
            frameData.videoFrame.close();

            if (frameData.isFirst) {
                const nowIndex = this.#remainingPlaylist[0];


                if(nowIndex === -1) {
                    this.event.sendStart();
                    this.#remainingPlaylist.shift();
                    console.log("Start => ", nowIndex);
                } else if (nowIndex === -2) {
                    this.event.sendRepeat();
                    this.#remainingPlaylist.shift();

                    console.log("Repeat => ", nowIndex);
                } else {
                    this.event.sendNext();
                    console.log("Next => ", nowIndex);
                }
            }
            else if (frameData.isEnd) {
                const nowIndex = this.#remainingPlaylist.shift();

                if(this.#remainingPlaylist.length === 0) {
                    console.log("End => ", nowIndex);
                    this.event.sendEnd();

                    return;
                }
            }
        }

        this.#updateTimeOut = setTimeout(this.update.bind(this), this.#updateTimestamp);
    }

    /**
     * 暫停播放影片。
     * @param sw true 代表暫停播放，false 代表恢復播放
     */
    public pause(sw: boolean) {
        if (sw === true && this.#updateTimeOut !== null) {
            clearTimeout(this.#updateTimeOut);

            return;
        }

        if (sw === false && this.#playList.length !== 0) {
            this.#updateTimeOut = setTimeout(this.update.bind(this), 33);

            return;
        }
    }

    public GetRenderTexture(): RenderTexture {
        return this.#renderTexture;
    }

    public unloadVideo() {
        this.videoChunks = [];
    }

    public closeDecoder() {
        if (this.#decoder !== null) {
            this.#decoder.closeDecoder();
            this.#decoder = null;
        }


    }
}