
import { VideoChunk, VideoFrameData } from "./wanin-player.interface";

type PlayListDequeue = (currentPlayList: number[]) => void;
type PlayListFinish = () => void;
// type PlayListFinish = () => void;

export default class Decoder {
    /** 一開始播放需要先放入解碼器佇列的數量 */
    private readonly firstInputDecoderNum = 3;

    /** 輸入解碼佇列最大值 */
    private readonly queueMaxIndex = 3;

    /** 解碼完畢畫面暫存佇列 */
    private readonly videoFrameQueue: VideoFrameData[] | null[] = new Array(this.queueMaxIndex + 1).fill(null);

    /** 解碼器 */
    private decoder: VideoDecoder;

    /** 所有播放清單的 Chunk */
    private videoChunks: VideoChunk[] = [];

    /** 目前播放的影片Chunk */
    private playingVideo: VideoChunk | null = null;

    /** 目前解碼佇列數量 */
    private inputQueue = 0;

    /** 解碼完畢畫面暫存佇列 畫面傳入佇列索引 */
    private videoFrameQueueSetIndex = 0;

    /** 解碼完畢畫面暫存佇列 畫面傳出佇列索引 */
    private videoFrameQueueGetIndex = 0;

    /** 是否播放中 */
    private isPlayer = false;

    /** timeout  */
    private timeout: number | null = null;

    private config: VideoDecoderConfig;

    /** InputQueue目前丟到第幾偵 */
    private inputQueueFramesIndex: number = -1;

    /** 播放清單 */
    public playListQueue: number[] = [];

    /** 播放清單列變化 Callback */
    public playListDequeue: PlayListDequeue | null = null;

    public playListFinish: PlayListFinish | null = null;

    // public playListFinish: PlayListFinish | null = null;

    // public getInputQueueFramesIndex(): number {
    //     return this.inputQueueFramesIndex;
    // }

    constructor(config: VideoDecoderConfig) {
        this.config = config;

        this.config.hardwareAcceleration = "prefer-hardware";

        this.decoder = new VideoDecoder({
            output: this.VideoFrameOutput.bind(this),
            error: this.decoderError.bind(this),
        });


        VideoDecoder.isConfigSupported(this.config).then(support => {
            console.log(
                `VideoDecoder's config ${JSON.stringify(support.config)} support: ${support.supported
                }`);
        });
    }

    /**
     * 播放狀態
     * @returns {boolean}  false 解碼器沒有在解碼
     */
    public getIsPlayer() {
        return this.isPlayer;
    }

    /**
     * 設定影片資料
     * @param chunks VideoChunk
     */
    public setVideoChunks(chunks: VideoChunk[]) {
        this.videoChunks = chunks;

        console.log('setVideoChunks =>', chunks);
    }

    /**
     * 開始播放影片
     * @param queue 播放清單
     */
    public async startPlayVideo(queue: number[]) {
        if (this.playingVideo !== null) { // 影片尚未播放完畢
            await this.flushDecodr(true);
        }

        this.playListQueue = [...queue];


        this.playNextVidoe(() => {
            this.isPlayer = true;

            for (let i = 0; i < this.firstInputDecoderNum; i++) {
                if (this.playingVideo) {
                    this.decoder.decode(this.playingVideo.chunks[this.inputQueueFramesIndex]);
                    this.inputQueueFramesIndex++;
                    this.inputQueue++;
                }
                else {
                    this.flushDecodr().then();
                    console.error(`正在播放的影片意外的被清空`);
                    return;
                }


            }

            this.updateVideoFrame();
        });
    }



    /**
     * 清除刷新目前播放資料。
     * @param {boolean} clearOutput 是否要清除輸出畫面佇列
     */
    public async flushDecodr(clearOutput = false) {
        if (this.timeout !== null) {
            clearTimeout(this.timeout)

            this.timeout = null;
        }

        this.inputQueueFramesIndex = -1;
        this.playingVideo = null;
        this.isPlayer = false;

        await this.decoder.flush();

        if (clearOutput) { // 清除輸出畫面佇列
            for (let i = 0; i < this.videoFrameQueue.length; i++) {
                // this.outputQueueFramesIndex = -1;
                const f = this.getFrameOutput();

                if (f === null) {
                    break;
                }

                f.videoFrame.close();
            }
        }
    }

    /**
     * VideoFrame丟入解碼器
     */
    private updateVideoFrame() {
        if (!this.isPlayer) {
            return;
        }

        if (!this.playingVideo) {
            this.flushDecodr();
            console.error("正在播放的影片意外的被清空");

            return;
        }

        if (this.inputQueue > this.queueMaxIndex) { // 畫面還沒被取走。所以等一下。
            this.timeout = setTimeout(this.updateVideoFrame.bind(this), 5);
            // console.log("待解碼畫面太多");
            return;
        }

        if (this.inputQueueFramesIndex >= this.playingVideo.chunks.length) {
            this.playNextVidoe(() => {
                this.updateVideoFrame();
            });

            return;
        }

        this.decoder.decode(this.playingVideo.chunks[this.inputQueueFramesIndex]);
        this.inputQueueFramesIndex++;
        this.inputQueue++;
        this.timeout = setTimeout(this.updateVideoFrame.bind(this), 10);
    }

    /**
     * 設定下一步影片
     * @param dequeue 
     * @returns 
     */
    private playNextVidoe(dequeue: VoidFunction | null = null) {
        // 待播影片資料 已經全數丟入解碼器。
        if (this.playListQueue.length === 0) {
            this.flushDecodr().then(() => {
                if (this.playListFinish) {
                    this.playListFinish();
                }
            });

            return;
        }

        const nextvideoId = this.playListQueue.shift();
        const _Chunk = this.videoChunks.find(v => v.id == nextvideoId);


        if (_Chunk) {
            this.playingVideo = _Chunk;
            this.inputQueueFramesIndex = 0;

            // 切換key Frame
            this.config.description = _Chunk.description
            this.decoder.configure(this.config);
            

            if (this.playListDequeue) {
                this.playListDequeue(this.playListQueue);
            }

            if (dequeue) {
                dequeue();
            }

            return;
        }
        else {
            this.flushDecodr().then();
            console.error(`播放清單找不到 video id = ${nextvideoId} 的影片`);
        }
    }

    private VideoFrameOutput(frame: VideoFrame) {
        // console.log(frame);
        // if (frame.timestamp === 0) {
        //     this.outputQueueFramesIndex = 0;
        // }
        // else {
        //     this.outputQueueFramesIndex++;
        // }

        if (this.videoFrameQueue[this.videoFrameQueueSetIndex] !== null) {
            this.videoFrameQueue[this.videoFrameQueueSetIndex]?.videoFrame.close();
            this.videoFrameQueue[this.videoFrameQueueSetIndex] = null;
        }

        if (frame.duration == null) { // 理論上 frame.duration 一定會有資料。
            console.error("找不到 frame.duration");
        } else {
            this.videoFrameQueue[this.videoFrameQueueSetIndex] = {
                id: frame.duration >> 1,
                framesIndex: frame.timestamp,
                videoFrame: frame,
                isEnd: !!(frame.duration & 1),
                isFirst: frame.timestamp === 0,
            }
        }

        this.videoFrameQueueSetIndex = this.videoFrameQueueSetIndex === this.queueMaxIndex ? 0 : this.videoFrameQueueSetIndex + 1;
    }

    /**
     * 取得解碼完畢的畫面
     * @returns 解碼完畢的畫面
     */
    public getFrameOutput(): VideoFrameData | null {
        const res = this.videoFrameQueue[this.videoFrameQueueGetIndex];

        if (res !== null) {
            this.videoFrameQueue[this.videoFrameQueueGetIndex] = null;
            this.inputQueue--;
            this.videoFrameQueueGetIndex = this.videoFrameQueueGetIndex === this.queueMaxIndex ? 0 : this.videoFrameQueueGetIndex + 1;
        }

        return res;
    }

    private decoderError(error: DOMException) {
        console.error("decoderError =>", error);
    }

    public closeDecoder() {
        if (this.decoder != null) {
            this.decoder.close();
        }
    }
}