import { RenderTexture } from "cc";

export interface VideoChunk {
  /**
   * 影片名稱
   */
  name: string,

  /**
   * 影片id 
   */
  id: number,
  /** 
   *  chunks.EncodedVideoChunk.timestamp => 修改為該畫面為第幾幀 從 1 開始 1、2、3、....
   *  chunks.EncodedVideoChunk.duration => 修改為該影片 id + 是否結尾 id << 1 | 結尾
   */
  chunks: EncodedVideoChunk[],
  width: number,
  height: number,
  description: Uint8Array,
  codec: string,
  updateTimestamp: number,
  totalFrames: number
}

export interface VideoFileOption {
  fileTypes: "mp4" | "webm",
}

export enum PlayMode {
  /**
   * 單次播放。
   * 
   * @description
   * 此播放模式會進行"插斷播放"。  
   * 即立即中止上一部影片並播放此次影片。  
   * 如不想插斷播放，請改用接續模式。
  */
  Once,

  /**
   * 循環播放。
   * 
   * @description
   * 此播放模式會進行"插斷播放"，  
   * 並持續循環播放 playList 中所有影片。  
   */
  RepeatAll,

  /**
   * 循環播放列表最後一個檔案。
   * 
   * 
   * 此播放模式會進行"插斷播放"，  
   * 並在播放一次 playList 中所有影片後， 
   * 循環播放最後一個影片。  
   *  
   *  @example 
   *  // 播放順序即為 0 1 2 3 3 3 3 ...。  
   *  play(PlayMode.RepeatLast, {0 ,1 ,2 ,3 } )  
   *  
   */
  RepeatLast,

  /**
   * 單次播放 (接續)。
   * 
   * @description
   * 此播放模式會進行"插斷播放"，  
   * 即等待上一次播放列表結束後，才接著播放此次影片。  
   * 如不想接續播放，請改用插斷模式。   
   */
  AppendOnce,

  /**
   * 循環播放 (接續)。
   * 
   * @description
   * 此播放模式會進行"接續播放"，  
   * 並持續循環播放 playList 中所有影片。  
   */
  AppendRepeatAll,

  /**
   * 循環播放列表最後一個檔案 (接續)。
   * 
   * @description
   * 此播放模式會進行"接續播放"，  
   * 並在播放一次 playList 中所有影片後，  
   * 循環播放最後一個影片。  
   * 
   * @example 
   * // 播放順序即為 (上一次 playList 結束後) 0 1 2 3 3 3 3 ...。
   * play( PlayMode.AppendRepeatLast, {0,1,2,3} )
   */
  AppendRepeatLast,
}

export interface VideoFrameData {
  id: number,
  framesIndex: number,
  isFirst: boolean,
  isEnd: boolean,
  /** 
   *  timestamp => 修改為該畫面為第幾幀 從 1 開始 1、2、3、....
   *  duration => 修改為該影片id
   */
  videoFrame: VideoFrame,
}

export enum ErrorCode {
  /**
   * 預設錯誤碼。
   */
  UnknownError,
  /**
   * 影片解碼錯誤。
   * @description 解碼器無法運行，常見原因是硬體資源不足或資料錯誤導。
   */
  DecoderError,
  /**
   * 播放器設定了不可用的參數。
   */
  InvalidParameter,
  /**
   * 播放器創建codec失敗。
   */
  CreateCodecFailed,
}

export interface WaninPlayerEvent {
  onStart: (() => void) | null;
  onEnd: (() => void) | null;
  onNext: (() => void) | null;
  onRepeat: (() => void) | null;
  onError: ((code: ErrorCode, msg: string) => void) | null;
  onStartOnce: (() => void) | null;
  onEndOnce: (() => void) | null;
  onNextOnce: (() => void) | null;
  onRepeatOnce: (() => void) | null;
  onErrorOnce: ((code: ErrorCode, msg: string) => void) | null;
}

export interface IWaninPlayer {
  event: WaninPlayerEvent;
  loadVideo(urls: RequestInfo[] | URL[]): Promise<void>;
  createDecoder(): void;
  play(mode?: PlayMode, list?: number[]): void;
  pause(sw: boolean): void;
  GetRenderTexture(): RenderTexture;
  unloadVideo(): void;
  closeDecoder(): void;
}