import { WaninPlayerEvent, ErrorCode } from "./wanin-player.interface";

export default class EventManager implements  WaninPlayerEvent   {
    public onStart: (() => void)| null = null;
    public onEnd: (() => void)| null = null;
    public onNext: (() => void)| null = null;
    public onRepeat: (() => void)| null = null;
    public onError: ((code: ErrorCode, msg: string) => void)| null = null;

    public onStartOnce: (() => void)| null = null;
    public onEndOnce: (() => void)| null = null;
    public onNextOnce: (() => void)| null = null;
    public onRepeatOnce: (() => void)| null = null;
    public onErrorOnce: ((code: ErrorCode, msg: string) => void)| null = null;

    public sendStart() {
        if(this.onStart !== null) {
            this.onStart();
        }

        if(this.onStartOnce !== null) {
            this.onStartOnce();
            this.onStartOnce = null;
        }
    }

    public sendEnd() {
        if(this.onEnd !== null) {
            this.onEnd();
        }

        if(this.onEndOnce !== null) {
            this.onEndOnce();
            this.onEndOnce = null;
        }
    }

    public sendNext() {
        if(this.onNext !== null) {
            this.onNext();
        }

        if(this.onNextOnce !== null) {
            this.onNextOnce();
            this.onNextOnce = null;
        }
    }

    public sendRepeat() {
        if(this.onRepeat !== null) {
            this.onRepeat();
        }

        if(this.onRepeatOnce !== null) {
            this.onRepeatOnce();
            this.onRepeatOnce = null;
        }
    }

    public sendError(code: ErrorCode, msg: string) {
        if(this.onError !== null) {
            this.onError(code, msg);
        }

        if(this.onErrorOnce !== null) {
            this.onErrorOnce(code, msg);
            this.onErrorOnce = null;
        }
    }
}