// @ts-ignore
import MP4Box from '../mp4box/mp4box.all.js';
import { VideoChunk, VideoFileOption } from './wanin-player.interface';

interface BufferWithFileStart extends ArrayBuffer {
  fileStart: number;
}

export class VideoFile {
  private static defaultVideoFileOption: VideoFileOption = {
    fileTypes: "mp4",
  }

  // private static _initialize = (() => {
  // })();

  public static getVideoData = async (urls: RequestInfo[] | URL[], option: VideoFileOption = VideoFile.defaultVideoFileOption): Promise<VideoChunk[]> => {
    const { fileTypes } = option;
    if (fileTypes == "mp4") {
      return Promise.all(
        urls.map((currentValue: RequestInfo | URL, index: number) => VideoFile.readMp4File(currentValue, index + 1))
      );
    }

    return [];
  }

  private static readMp4File = async (url: RequestInfo | URL, id: number, name?: string) => new Promise<VideoChunk>((resolve, reject) => {
    let mp4box = MP4Box.createFile();
    let trackId = 0;
    let sampleNum = 0;
    const res: VideoChunk =
    {
      name: name || url.toString().match(/[/\\]([^/\\]+?)(\.\w+)?$/)?.[1] || "",
      id,
      chunks: [],
      width: 0,
      height: 0,
      description: new Uint8Array(0),
      codec: "",
      updateTimestamp: 0,
      totalFrames: 0,
    };
    mp4box.onSamples = (id: any, user: any, samples: any) => {
      res.updateTimestamp = (samples[0].duration / samples[0].timescale) * 1000
      res.totalFrames = samples.length;

      samples.forEach((sample: any, index: number) => {
        res.chunks.push(
          new EncodedVideoChunk({
            type: sample.is_sync ? "key" : "delta", // 是否有關鍵貞       
            timestamp: index, // 修改為目前偵數
            duration: (res.id << 1) | (index === res.totalFrames - 1 ? 1 : 0),
            // timestamp: sample.dts * timescale, // chunk 開始的時間戳 => 更改為 id
            // duration: sample.duration * timescale, // 大小 
            data: sample.data,  // 資料
          })
        );
      })

      mp4box.releaseUsedSamples(trackId, sampleNum);
      mp4box.stop();
      mp4box.flush();
      mp4box = null;

      resolve(res);
    }

    mp4box.onReady = (info: any) => {
      const tracks = info.tracks[0];
      if (tracks) {
        trackId = tracks.id;
        sampleNum = tracks.nb_samples;
        mp4box.setExtractionOptions(trackId, 'video', { nbSamples: sampleNum });
        // 生成VideoDecoder.configure需要的description信息
        const entry = mp4box.moov.traks[0].mdia.minf.stbl.stsd.entries[0];
        const stream = new MP4Box.DataStream(undefined, 0, MP4Box.DataStream.BIG_ENDIAN);
        entry.avcC.write(stream);
        res.description = new Uint8Array(stream.buffer.slice(8));
        res.width = tracks.track_width;
        res.height = tracks.track_height;
        res.codec = tracks.codec;
        mp4box.start();
      } else {
        mp4box = null;
        reject(new Error("找不到影片資料"));
      }
    }

    mp4box.onError = (e: Error) => {
      reject(e);
    };

    fetch(url)
      .then(res => {

        return res.arrayBuffer()
      })
      .then(buffer => {
        const bufferWithStart = buffer as BufferWithFileStart;
        bufferWithStart.fileStart = 0;

        mp4box.appendBuffer(bufferWithStart);
      })
      .catch((err) => reject(err))
  });
}